22	/**
23	 * Enforces that no two owners share a household, i.e. have the same last name and the same address.
24	 * Both fields are compared case-insensitively and with runs of whitespace collapsed to a single
25	 * space (and surrounding whitespace trimmed), so values that differ only in letter case or spacing
26	 * are still treated as the same. The comparison is done in memory because the stored last name is
27	 * not kept in a normalized form, so a household cannot be matched reliably with a database query.
28	 */
29	@Component
30	public class OwnerHouseholdUniquenessValidator {
31	
32	    private final ClinicService clinicService;
33	
34	    public OwnerHouseholdUniquenessValidator(ClinicService clinicService) {
35	        this.clinicService = clinicService;
36	    }
37	
38	    /**
39	     * Rejects an owner whose last name and address already belong to an existing owner.
40	     *
41	     * @param lastName the last name of the owner being created
42	     * @param address  the address of the owner being created
43	     * @throws DuplicateOwnerHouseholdException if another owner already has this last name and
44	     *                                          address
45	     */
46	    public void validateUnique(String lastName, String address) {
47	        String key = HouseholdKey.of(lastName, address);
48	        boolean duplicate = this.clinicService.findAllOwners().stream()
49	            .anyMatch(existing -> HouseholdKey.of(existing.getLastName(), existing.getAddress()).equals(key));
50	        if (duplicate) {
51	            throw new DuplicateOwnerHouseholdException(lastName, address);
52	        }
53	    }
54	}
