17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.model.BusinessDayAdjuster;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.audit.OwnerAuditLogger;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
42	import org.springframework.samples.petclinic.rest.validation.CityOwnerCapacityValidator;
43	import org.springframework.samples.petclinic.rest.validation.CityOwnerCounter;
44	import org.springframework.samples.petclinic.rest.validation.CustomerCodeGenerator;
45	import org.springframework.samples.petclinic.rest.validation.DailyRegistrationCapacityValidator;
46	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
47	import org.springframework.samples.petclinic.rest.validation.MembershipNumberGenerator;
48	import org.springframework.samples.petclinic.rest.validation.OwnerEmailUniquenessValidator;
49	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
50	import org.springframework.samples.petclinic.rest.validation.NamesakeCounter;
51	import org.springframework.samples.petclinic.rest.validation.OwnerHouseholdRegistrar;
52	import org.springframework.samples.petclinic.rest.validation.OwnerHouseholdUniquenessValidator;
53	import org.springframework.samples.petclinic.rest.validation.OwnerTelephoneUniquenessValidator;
54	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
55	import org.springframework.samples.petclinic.service.ClinicService;
56	import org.springframework.security.access.prepost.PreAuthorize;
57	import org.springframework.web.bind.annotation.CrossOrigin;
58	import org.springframework.web.bind.annotation.RequestMapping;
59	import org.springframework.web.bind.annotation.RestController;
60	import org.springframework.web.util.UriComponentsBuilder;
61	
62	import jakarta.transaction.Transactional;
63	
64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    private final OwnerTelephoneUniquenessValidator telephoneUniquenessValidator;
82	
83	    private final OwnerEmailUniquenessValidator emailUniquenessValidator;
84	
85	    private final OwnerHouseholdUniquenessValidator householdUniquenessValidator;
86	
87	    private final OwnerHouseholdRegistrar householdRegistrar;
88	
89	    private final NamesakeCounter namesakeCounter;
90	
91	    private final CityOwnerCounter cityOwnerCounter;
92	
93	    private final CityOwnerCapacityValidator cityOwnerCapacityValidator;
94	
95	    private final DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator;
96	
97	    private final OwnerAuditLogger ownerAuditLogger;
98	
99	    public OwnerRestControllerV1(ClinicService clinicService,
100	                                 OwnerMapper ownerMapper,
101	                                 PetMapper petMapper,
102	                                 VisitMapper visitMapper,
103	                                 OwnerTelephoneUniquenessValidator telephoneUniquenessValidator,
104	                                 OwnerEmailUniquenessValidator emailUniquenessValidator,
105	                                 OwnerHouseholdUniquenessValidator householdUniquenessValidator,
106	                                 OwnerHouseholdRegistrar householdRegistrar,
107	                                 NamesakeCounter namesakeCounter,
108	                                 CityOwnerCounter cityOwnerCounter,
109	                                 CityOwnerCapacityValidator cityOwnerCapacityValidator,
110	                                 DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator,
111	                                 OwnerAuditLogger ownerAuditLogger) {
112	        this.clinicService = clinicService;
113	        this.ownerMapper = ownerMapper;
114	        this.petMapper = petMapper;
115	        this.visitMapper = visitMapper;
116	        this.telephoneUniquenessValidator = telephoneUniquenessValidator;
117	        this.emailUniquenessValidator = emailUniquenessValidator;
118	        this.householdUniquenessValidator = householdUniquenessValidator;
119	        this.householdRegistrar = householdRegistrar;
120	        this.namesakeCounter = namesakeCounter;
121	        this.cityOwnerCounter = cityOwnerCounter;
122	        this.cityOwnerCapacityValidator = cityOwnerCapacityValidator;
123	        this.dailyRegistrationCapacityValidator = dailyRegistrationCapacityValidator;
124	        this.ownerAuditLogger = ownerAuditLogger;
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
130	        Collection<Owner> owners;
131	        if (lastName != null) {
132	            owners = this.clinicService.findOwnerByLastName(lastName);
133	        } else {
134	            owners = this.clinicService.findAllOwners();
135	        }
136	        if (owners.isEmpty()) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
145	        Owner owner = this.clinicService.findOwnerById(ownerId);
146	        if (owner == null) {
147	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
148	        }
149	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
150	    }
151	
152	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
153	    @Override
154	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
155	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
156	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
157	        HttpHeaders headers = new HttpHeaders();
158	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
159	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
160	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
161	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
162	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
163	        this.dailyRegistrationCapacityValidator.validateHasCapacity(owner.getRegistrationDate());
164	        this.telephoneUniquenessValidator.validateUnique(owner.getTelephone());
165	        this.emailUniquenessValidator.validateUnique(owner.getEmail());
166	        this.cityOwnerCapacityValidator.validateHasCapacity(owner.getCity());
167	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
168	            this.householdUniquenessValidator.validateUnique(owner.getLastName(), owner.getAddress());
169	        } else {
170	            this.householdRegistrar.assignHousehold(owner);
171	        }
172	        owner.setNamesakeCount(this.namesakeCounter.count(owner.getFirstName(), owner.getLastName()));
173	        owner.setCustomerCode(CustomerCodeGenerator.generate(owner.getCity(), owner.getLastName(),
174	            this.cityOwnerCounter.count(owner.getCity())));
175	        this.clinicService.saveOwner(owner);
176	        owner.setMembershipNumber(MembershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
177	        this.ownerAuditLogger.logCreated(owner);
178	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
179	        headers.setLocation(UriComponentsBuilder.newInstance()
180	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
181	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
187	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
188	        if (currentOwner == null) {
189	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	        }
191	        currentOwner.setAddress(ownerFieldsDto.getAddress());
192	        currentOwner.setCity(ownerFieldsDto.getCity());
193	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
194	        currentOwner.setLastName(ownerFieldsDto.getLastName());
195	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
196	        this.clinicService.saveOwner(currentOwner);
197	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
198	    }
199	
200	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
201	    @Transactional
202	    @Override
203	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
204	        Owner owner = this.clinicService.findOwnerById(ownerId);
205	        if (owner == null) {
206	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
207	        }
208	        this.clinicService.deleteOwner(owner);
209	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
210	    }
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
215	        Owner owner = this.clinicService.findOwnerById(ownerId);
216	        if (owner == null) {
217	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
218	        }
219	        HttpHeaders headers = new HttpHeaders();
220	        Pet pet = petMapper.toPet(petFieldsDto);
221	        owner.setId(ownerId);
222	        pet.setOwner(owner);
223	        pet.getType().setName(null);
224	        this.clinicService.savePet(pet);
225	        PetDto petDto = petMapper.toPetDto(pet);
226	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
227	            .buildAndExpand(pet.getId()).toUri());
228	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
229	    }
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
233	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
234	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
235	        if (currentOwner != null) {
236	            Pet currentPet = this.clinicService.findPetById(petId);
237	            if (currentPet != null) {
238	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
239	                currentPet.setName(petFieldsDto.getName());
240	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
241	                this.clinicService.savePet(currentPet);
242	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
243	            }
244	        }
245	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
246	    }
247	
248	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
249	    @Override
250	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
251	        HttpHeaders headers = new HttpHeaders();
252	        Visit visit = visitMapper.toVisit(visitFieldsDto);
253	        Pet pet = new Pet();
254	        pet.setId(petId);
255	        visit.setPet(pet);
256	        this.clinicService.saveVisit(visit);
257	        VisitDto visitDto = visitMapper.toVisitDto(visit);
258	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
259	            .buildAndExpand(visit.getId()).toUri());
260	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
261	    }
262	
263	
264	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
265	    @Override
266	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
267	        Owner owner = this.clinicService.findOwnerById(ownerId);
268	        if (owner != null) {
269	            Pet pet = owner.getPet(petId);
270	            if (pet != null) {
271	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
272	            }
273	        }
274	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
275	    }
276	}
